// Generates src/NpAspire.Api/Authorization/Permissions.g.cs from infra/auth0/permissions.json, the single source
// of truth for permissions and roles (docs/spec.md §5.1). Terraform configures Auth0 from the same file.
//
// Run from the repository root:
//   node scripts/generate-permissions.mjs
//   node scripts/generate-permissions.mjs --check   (fails if the committed output is stale; used by CI)
//
// The generated file is committed and never edited by hand.
import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { parseArgs } from 'node:util';

const manifestPath = resolve('infra/auth0/permissions.json');
const outputPath = resolve('src/NpAspire.Api/Authorization/Permissions.g.cs');

const { values } = parseArgs({ options: { check: { type: 'boolean', default: false } } });

function fail(message) {
  console.error(`permissions.json: ${message}`);
  process.exit(1);
}

const manifest = JSON.parse(readFileSync(manifestPath, 'utf8'));
const permissions = manifest.permissions ?? [];
const roles = manifest.roles ?? [];

if (permissions.length === 0) {
  fail('no permissions defined');
}

const values_ = permissions.map((permission) => permission.value);

const duplicates = values_.filter((value, index) => values_.indexOf(value) !== index);
if (duplicates.length > 0) {
  fail(`duplicate permissions: ${[...new Set(duplicates)].join(', ')}`);
}

for (const value of values_) {
  if (!/^[a-z][a-z0-9_]*:[a-z][a-z0-9_]*$/.test(value)) {
    fail(`permission "${value}" is not in <action>:<resource> form`);
  }
}

// Every permission a role grants must exist, or Auth0 and the API would disagree about what a role means.
for (const role of roles) {
  for (const permission of role.permissions ?? []) {
    if (!values_.includes(permission)) {
      fail(`role "${role.name}" grants unknown permission "${permission}"`);
    }
  }
}

// Exactly one role is assigned on first login (the post-login Action).
const defaultRoles = roles.filter((role) => role.default === true).map((role) => role.name);
if (defaultRoles.length !== 1) {
  fail(
    defaultRoles.length === 0
      ? 'no role is marked "default": true'
      : `more than one default role: ${defaultRoles.join(', ')}`,
  );
}

// read:profile -> ReadProfile
function memberName(value) {
  return value
    .split(/[:_]/)
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join('');
}

const constants = permissions
  .map(
    (permission) => `    /// <summary>${permission.description}</summary>
    public const string ${memberName(permission.value)} = "${permission.value}";`,
  )
  .join('\n\n');

const policies = values_
  .map((value) => `        builder.AddPolicy(${memberName(value)}, policy => policy.RequireClaim(ClaimName, ${memberName(value)}));`)
  .join('\n');

const generated = `// <auto-generated>
//     Generated from infra/auth0/permissions.json by scripts/generate-permissions.mjs.
//     Edit the manifest and re-run the script; changes made here are lost.
// </auto-generated>

using Microsoft.AspNetCore.Authorization;

namespace NpAspire.Api.Authorization;

/// <summary>
/// Permissions granted by Auth0 RBAC. The API authorizes on these names, never on role names, so roles can be
/// changed in Auth0 without touching the code.
/// </summary>
public static class Permissions
{
    /// <summary>Access-token claim Auth0 puts the caller's permissions in.</summary>
    public const string ClaimName = "permissions";

${constants}

    /// <summary>Every permission, in manifest order.</summary>
    public static readonly string[] All =
    [
${values_.map((value) => `        ${memberName(value)},`).join('\n')}
    ];

    /// <summary>Adds one authorization policy per permission, named after the permission.</summary>
    public static AuthorizationBuilder AddPermissionPolicies(this AuthorizationBuilder builder)
    {
${policies}

        return builder;
    }
}
`;

const current = (() => {
  try {
    return readFileSync(outputPath, 'utf8');
  } catch {
    return null;
  }
})();

if (values.check) {
  if (current !== generated) {
    console.error(
      `${outputPath} is out of date. Run "node scripts/generate-permissions.mjs" and commit the result.`,
    );
    process.exit(1);
  }

  console.log(`${outputPath} is up to date.`);
} else if (current === generated) {
  console.log(`${outputPath} is already up to date.`);
} else {
  writeFileSync(outputPath, generated);
  console.log(`Wrote ${outputPath} (${permissions.length} permissions, ${roles.length} roles).`);
}
